\begin{definition}
    $\chi$ denotes the $p$-biased 
    Fourier character,
    \[\chi(0) = \sqrt{\frac{p}{1-p}}, \qquad \chi(1) = -\sqrt{\frac{1-p}{p}}.\]
    For $H$ a subset or multi-subset of $\binom{[n]}{2}$, let $\chi_H(G) \defeq \prod_{e \in H}\chi(G_e)$.
\end{definition}

\begin{definition}
