    $\indset{H}(G) = \prod_{e \in H}(1-G_e)$.
\end{definition}

\begin{proposition}
    \label{lem:independent-set-indicator}
    For $e \in \{0,1\}$, $1 + \sqrt{\frac{p}{1-p}}\chi(e) = \frac{1}{1-p}(1-e)$.
    Therefore, for any $H \subseteq \binom{[n]}{2}$,
    \[ \sum_{T \subseteq H} \left(\frac{p}{1-p}\right)^{\abs{T}/2}\chi_T(G) = \frac{1}{(1-p)^{\abs{H}}}\cdot \indset{H}(G).\]
\end{proposition}

\begin{definition}[Ribbon]
\label{def:ribbon}
    A ribbon is a tuple $R = (V(R), E(R), A_R, B_R)$,
    where $(V(R), E(R))$ is an undirected multigraph without self-loops,
    $V(R) \subseteq [n]$, and $A_R, B_R \subseteq V(R)$.
    Let $C_R \defeq V(R) \setminus (A_R \cup B_R)$.
\end{definition}

\begin{definition}[Matrix for a ribbon]
    For a ribbon $R$, the matrix $M_R$ has rows and columns 
    indexed by all subsets of $[n]$ and has a single nonzero entry,
    \[ M_R[I,J] = \begin{cases}
        \displaystyle\chi_{E(R)}(G) 
        & I = A_R, J = B_R\\
        0 & \text{Otherwise}
    \end{cases}\]
\end{definition}

\begin{definition}[Ribbon isomorphism]
Two ribbons $R, S$ are isomorphic, or have the same shape, if there is a bijection between $V(R)$ and $V(S)$ which is a multigraph isomorphism 
between $E(R), E(S)$ and 
is a bijection from $A_R$ to $A_S$ and $B_R$ to $B_S$.
Equivalently, letting $S_n$ permute the vertex labels of a ribbon, the two ribbons are in the same $S_n$-orbit.
\end{definition}

\begin{definition}[Shape]
\label{def:shape}
    A shape is an equivalence class of ribbons with the same shape. Each shape 
    has associated with it
    a representative $\alpha = (V(\alpha), E(\alpha), U_\alpha, V_\alpha)$, where $U_\alpha,V_\alpha \subseteq V(\alpha)$.
