\end{definition}

\begin{definition}[Automorphism]
    For a shape $\alpha$, $\Aut(\al)$ is the group of bijections from $V(\al)$ to itself such that $U_\al$ and $V_\al$ are fixed as sets
    and the map is a multigraph automorphism on $E(\al)$.
    Equivalently, $\Aut(\al)$ is the stabilizer subgroup (of $S_n$) of any ribbon of shape $\al$.
\end{definition}

\begin{definition}[Proper]
    A ribbon or shape is proper if it has no multi-edges. Otherwise, it is improper.
    Let $\mul_\al(e)$ be the multiplicity of edge $e$ in ribbon or shape $\al$.
\end{definition}

\begin{definition}[Trivial shape]
    A shape $\al$ is trivial if $V(\alpha) = U_\al = V_\al$ and
