\begin{definition}[Quasi-indicator function]
Given a set of edges $E \subseteq \binom{[n]}{2}$, we define the quasi-missing edge indicator function $q_E$ to be 
\[
q_E = (1-p)^{|E|+1}\sum_{E' \subseteq E}{\frac{1}{(|E|+1)\binom{|E|}{|E'|}}\left(\frac{1}{1-p}\right)^{|E'|}1_{\forall e \in E', e \notin E(G)}}
\] 
\end{definition}

\begin{definition}[Augmented ribbon]\label{def:augmented-ribbon}
