\end{definition}

\begin{definition}[Matrix for an augmented ribbon]
    The matrix $M_R$ has rows and columns indexed by all subsets of $[n]$, with entries:
    \[M_R[I,J] = \begin{cases}
        \displaystyle\prod_{\text{edge-functions }f\text{ on }S \subseteq V(R)}f(G|_S) & I = A_R, J = B_R\\
        0 & \text{Otherwise}
    \end{cases}\]
\end{definition}

\begin{definition}[Permissible]\label{def:permissible-ribbon}
We say that an augmented ribbon $R$ is permissible if the following conditions are satisfied:
\begin{enumerate}
\item All vertices $v \in V(R)$ are reachable from $A_R \cup B_R$ using the Fourier character edges.
\item There is a missing edge indicator for all edges within $A_R$ and a missing edge indicator for all edges within $B_R$.
\item For any vertex $v \in V(R) \setminus (A_R \cap B_R)$ which is reachable from $(A_R \cup B_R) \setminus (A_R \cap B_R)$ without passing through $(A_R \cap B_R)$, there is a missing edge indicator for all edges between $(A_R \cap B_R)$ and $v$.

\item For each connected component $C$ of $R \setminus (A_R \cap B_R)$ which is disconnected from $A_R \cup B_R$, there is precisely one pair of vertices $u \in A_R \cap B_R$ and $w \in C$ such that $(u,w) \in E(R)$ and $R$ contains the quasi-missing edge indicator $q_{\left((A_R \cap B_R) \times C\right) \setminus \{u,w\}}$ for all other edges between $A_R \cap B_R$ and $C$.
\item There are no other (quasi-)missing edge indicators, and the Fourier character edges are disjoint from the (quasi-)missing edge indicators.
\end{enumerate}
A shape is permissible if any (equivalently, all) of its ribbons are permissible.
\end{definition}

\begin{definition}
    For a permissible shape or ribbon $R$, let:
    \[m(R) = \left(\frac{1}{1-p}\right)^{\binom{|A_R|}{2}/2 + \binom{|B_R|}{2}/2  - \binom{|A_R \cap B_R|}{2} + |V(R) \setminus (A_R \cup B_R)| \cdot |A_R \cap B_R|}.\]
\end{definition}

\begin{corollary}\label{cor:conditioning-recursive}
Given a set of edges $E$, if we know that at most $k < |E|$ of the edges of $E$ are in $E(G)$, then
\[\chi_E = (-1)^{|E| - k}\sum_{E' \subseteq E:|E'| \le k} \binom{|E| - 1 - |E'|}{|E| - 1 - k} \left(-\sqrt{\frac{p}{1-p}}\right)^{|E| - |E'|}\chi_{E'}.\]
\end{corollary}

