We start by proving the following 2 auxiliary statements:

\begin{lemma}\label{shapecountboundone}
For all $v \in \mathbb{N}$ and all $e,k \in \mathbb{N} \cup \{0\}$, there are at most
\[
2\dsos^{k+1}{2^v}v^{2e}
\]
permissible shapes $\alpha$ with degree at most $\dsos$ such that $|V(\alpha) \setminus (U_{\alpha} \cap V_{\alpha})| = v$, there are $e$ edges in $E(\alpha)$ which are not incident to a vertex in $U_{\alpha} \cap V_{\alpha}$,
and $\alpha \setminus (U_{\alpha} \cap V_{\alpha})$ has $k$ connected components which are disconnected from $U_{\alpha} \cup V_{\alpha}$.
\end{lemma}
\begin{proof}
We can choose such a shape $\alpha$ as follows:
\begin{enumerate}
\item First choose the number of vertices in $U_{\alpha} \cap V_{\alpha}$. There are at most $\dsos+1$ possibilities for this as $0 \leq |U_{\alpha} \cap V_{\alpha}| \leq \dsos$.
\item Indicate whether $U_{\alpha} \setminus V_{\alpha}$ and $V_{\alpha} \setminus U_{\alpha}$ are non-empty. There are $4$ choices for this.
\item Order the vertices in $V(\alpha) \setminus (U_{\alpha} \cap V_{\alpha})$ so that the vertices in $U_{\alpha} \setminus V_{\alpha}$ come first (if there are any), followed by the vertices in $V_{\alpha} \setminus U_{\alpha}$ (if there are any), followed by the vertices in each of the $k$ connected components of $\alpha \setminus (U_{\alpha} \cap V_{\alpha})$ which are disconnected from $U_{\alpha} \cup V_{\alpha}$ (where we put the vertex which has an edge to $U_{\alpha} \cap V_{\alpha}$ first), followed by any remaining vertices.
\item For each vertex except for the first vertex, indicate whether it is in the same group as the previous vertex or is the first vertex of the next group. There are at most $2^{v-1}$ choices for this.
\item For the first vertex $w_i$ in each connected component $W_i$ of $\alpha \setminus (U_{\alpha} \cap V_{\alpha})$ which is disconnected from $U_{\alpha} \cup V_{\alpha}$, choose which vertex in $U_{\alpha} \cap V_{\alpha}$ $w_i$ is adjacent to. There are at most $\dsos^{k}$ choices for this.
\item For each edge which is not incident to a vertex in $U_{\alpha} \cap V_{\alpha}$, choose its two endpoints. There are at most $v^{2e}$ choices for this.
\item The missing edge indicators and quasi-missing edge indicators are fixed because $\alpha$ is a permissible shape.
\end{enumerate}
\end{proof}

\begin{lemma}
For all $v \in \mathbb{N}$ and all $e,k,C \in \mathbb{N} \cup \{0\}$, there are at most 
\[
2(\dsos+1)^{k+1}{8^v}{4^e}((C+4){\dsos})^{(C+2)\dsos}v^{\max{\{0,e + k - v - C\dsos\}}}
\]
permissible shapes $\alpha$ with degree at most $\dsos$ such that $|V(\alpha) \setminus (U_{\alpha} \cap V_{\alpha})| = v$, there are $e$ edges in $E(\alpha)$ which are not incident to a vertex in $U_{\alpha} \cap V_{\alpha}$,
and $\alpha \setminus (U_{\alpha} \cap V_{\alpha})$ has $k$ connected components which are disconnected from $U_{\alpha} \cup V_{\alpha}$.
\end{lemma}
\begin{proof}
This can be proved in the same way as Lemma \ref{shapecountboundone} except that we handle the edges which are not incident to a vertex in $U_{\alpha} \cap V_{\alpha}$ in a different way. We order these based on a breadth first search where we start with the vertices in $U_{\alpha} \cup V_{\alpha}$ in the queue.
\begin{enumerate}
\item For each new vertex which we reach, indicate whether it will be reached again by one of the first $C\dsos$ edges which do not go to a new vertex. Also indicate whether it has edges incident to it which lead to a new vertex (in which case it should be added to the queue) or not.
\item For each edge, first indicate whether it starts from the same vertex as the previous edge or starts from the next vertex in the queue. Then indicate whether this edge reaches a new vertex or goes to a vertex which has already been reached. If it is one of the first $(C+2)\dsos$ edges which goes to a vertex which has already been reached, indicate which vertex this is. Note that there are at most $(C+4)\dsos$ choices for this as this vertex is either in $U_{\alpha} \cup V_{\alpha}$ or is one of the indicated destinations for these edges (of which there are at most $(C+2)\dsos$). If this is a later edge which goes to a vertex which has already been reached, specify this vertex (there are at most $v$ choices for this).
\end{enumerate}
We now observe that at least $v - k - 2\dsos$ edges which are not incident to a vertex in $U_{\alpha} \cap V_{\alpha}$ are needed to connect $U_{\alpha} \cup V_{\alpha}$ to the rest of $\alpha$, so there are at most $e + k - v + 2\dsos$ edges which do not go to a new vertex. After we take the first $(C+2)\dsos$ such edges, there are at most $e + k - v - C\dsos$ such edges left.
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Observe that
\begin{align*}
&\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma \in \calL}}\lam'_\sigma \frac{M_\sigma}{|Aut(\sigma)|}\right)\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma' \in \calL}}\lam'_{\sigma'} \frac{M_{\sigma'}}{|Aut(\sigma')|}\right)^\T \\
= &\sum_{j=0}^{\dsos}{\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma \in \calL: |V_{\sigma}| = j}}\lam'_\sigma \frac{M_\sigma}{|Aut(\sigma)|}\right)\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma' \in \calL: |V_{\sigma'}| = j}}\lam'_{\sigma'} \frac{M_{\sigma'}}{|Aut(\sigma')|}\right)^\T}
\end{align*}
Thus, it is sufficient to show that 
\[
\sum_{j=0}^{\dsos}{\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma \in \calL: |V_{\sigma}| = j}} w_j\lam'_\sigma \frac{M_\sigma}{|Aut(\sigma)|}\right)\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma' \in \calL: |V_{\sigma'}| = j}}w_j \lam'_{\sigma'} \frac{M_{\sigma'}}{|Aut(\sigma')|}\right)^\T} \succeq n^{-O(\dsos)}\pi
\]
for some weights $w_0,\ldots,w_{\dsos} \in [0,1]$.
To show this, we will show that if we choose the weights $w_0,\ldots,w_{\dsos} \in [0,1]$ carefully then all of the terms where $\sigma$ is non-trivial or $\sigma'$ is non-trivial can be charged to $\pi$.
\begin{definition}
Define ${\pi}_j$ to be the matrix such that $M_{AB} = 1$ if $A = B$ and $A$ is an independent set of size $j$ in $G$ and $M_{AB} = 0$ otherwise.
\end{definition}
\begin{proposition}
$\pi = \sum_{j=0}^{\dsos}{\pi_j}$
\end{proposition}
\begin{definition}
Define $\lambda'_{\pi_j} \approx \left(\frac{k}{n}\right)^{\frac{j}{2}}$ to be the coefficient $\lambda'_{\sigma}$ of the shape $\sigma$ where $V(\sigma) = U_{\sigma} = V_{\sigma}$, $|U_{\sigma}| = j$, and there is a missing edge indicator for every possible edge in $V(\sigma) = U_{\sigma} = V_{\sigma}$.
\end{definition}
We will choose our weights so that the following condition is satisfied. For all $C'$-sparse $\sigma$ and $\sigma'$ such that $\sigma$ is non-trivial or $\sigma'$ is non-trivial, letting $i = |U_{\sigma}|$ and letting $i' = |U_{\sigma'}|$,
\[
-{w_j}\lam'_{\sigma}\lam'_{\sigma'} \frac{{M_\sigma}M_{\sigma'}^{\T} + {M_{\sigma'}}M_{\sigma}^{\T}}{|Aut(\sigma)| \cdot |Aut(\sigma')|} \preceq \frac{1}{c(\sigma)c(\sigma')\dsos}\left(w_i{\lambda'}_{\pi_i}^2{\pi_i} + w_{i'}{\lambda'}_{\pi_{i'}}^2{\pi_{i'}}\right)
\]
To see why this condition is sufficient, observe that since $\sum_{\alpha}{\frac{1}{c(\alpha)}} \leq \frac{1}{4}$, 
\begin{enumerate}
    \item For all non-trivial $\sigma$ such that $|V_{\sigma}| = i$ and  $|V_{\sigma}| = j$,
    \[
    \sum_{\sigma': |V_{\sigma'}| = j}{\frac{1}{c(\sigma)c(\sigma')\dsos}w_i{\lambda'}_{\pi_i}^2{\pi_i}} \preceq \frac{2}{c(\sigma)\dsos}w_i{\lambda'}_{\pi_i}^2{\pi_i}
    \] 
    Summing this over all non-trivial $\sigma$ such that $|V_{\sigma}| = i$ and $|V_{\sigma}| = j$, we have that 
    \[
    \sum_{\sigma: |U_{\sigma}| = i, |V_{\sigma}| = j, \sigma \text{ is non-trivial}}{\sum_{\sigma': |V_{\sigma'}| = j }{\frac{1}{c(\sigma)c(\sigma')\dsos}w_i{\lambda'}_{\pi_i}^2{\pi_i}}} \preceq \frac{1}{2\dsos}w_i{\lambda'}_{\pi_i}^2{\pi_i}
    \]
    \item When $\sigma$ is trivial, 
    $\sum_{\sigma': |V_{\sigma'}| = j, \sigma' \text{ is non-trivial}}{\frac{1}{c(\sigma')\dsos}w_j{\lambda'}_{\pi_j}^2{\pi_j}} \preceq \frac{1}{4\dsos}w_j{\lambda'}_{\pi_j}^2{\pi_j}$
\end{enumerate}
Thus, we have that 
\[
\sum_{j=0}^{\dsos}{\sum_{\sigma,\sigma': |V_{\sigma}| = |V_{\sigma'}| = j, \sigma \text{ or } \sigma' \text{ is non-trivial}}{\frac{1}{c(\sigma)c(\sigma')\dsos}w_{|U_{\sigma}|}{\lambda'}_{\pi_{|U_{\sigma}|}}^2{\pi_{|U_{\sigma}|}}}} \preceq \sum_{i=0}^{\dsos}{\frac{\dsos+1}{2\dsos}w_i{\lambda'}_{\pi_i}^2{\pi_i}}
\]
The $w_{i'}{\lambda'}_{\pi_{i'}}^2{\pi_{i'}}$ terms can be bounded in the same way. This implies that
\[
\sum_{j=0}^{\dsos}{\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma \in \calL: |V_{\sigma}| = j}}\lam'_\sigma \frac{M_\sigma}{|Aut(\sigma)|}\right)\left(\sum_{\substack{\text{sparse,}\\\text{permissible} \\ \sigma' \in \calL: |V_{\sigma'}| = j}}\lam'_{\sigma'} \frac{M_{\sigma'}}{|Aut(\sigma')|}\right)^\T} \succeq \sum_{i=0}^{\dsos}{\frac{1}{4}w_i{\lambda'}_{\pi_i}^2{\pi_i}} \succeq \frac{1}{4}\left(\min_{i \in [0,\dsos]}{\{w_i{\lambda'}_{\pi_i}^2\}}\right)\pi
\]
We now choose the weights so that for all $\sigma$ and $\sigma'$ such that $\sigma$ is non-trivial or $\sigma'$ is non-trivial, letting $i = |U_{\sigma}|$ and letting $i' = |U_{\sigma'}|$,
\[
-{w_j}\lam'_{\sigma}\lam'_{\sigma'} \frac{{M_\sigma}M_{\sigma'}^{\T} + {M_{\sigma'}}M_{\sigma}^{\T}}{|Aut(\sigma)| \cdot |Aut(\sigma')|} \preceq \frac{1}{c(\sigma)c(\sigma')\dsos}\left(w_i{\lambda'}_{\pi_i}^2{\pi_i} + w_{i'}{\lambda'}_{\pi_{i'}}^2{\pi_{i'}}\right)
\]
Observe that for all $a,b > 0$
\[
\left(a\frac{M_\sigma}{|Aut(\sigma)|} - b\frac{M_{\sigma'}}{|Aut(\sigma')|}\right)\left(a\frac{M_{\sigma}^T}{|Aut(\sigma)|} - b\frac{M_{\sigma'}^T}{|Aut(\sigma')|}\right) \succeq 0
\]
and 
\[
a^2\frac{M_{\sigma}M_{\sigma}^T}{|Aut(\sigma)|^2} + b^2\frac{M_{\sigma'}M_{\sigma'}^T}{|Aut(\sigma)|^2} \preceq a^2\norm{\frac{M_{\sigma}}{|Aut(\sigma)|}}^2{\pi_i} + b^2\norm{\frac{M_{\sigma'}}{|Aut(\sigma')|}}^2{\pi_{i'}}
\]
Choosing $a = \frac{\sqrt{\frac{w_i}{c(\sigma)c(\sigma')\dsos}}{\lambda'}_{\pi_i}|Aut(\sigma)|}{\norm{M_{\sigma}}}$ and $b = \frac{\sqrt{\frac{w_{i'}}{c(\sigma)c(\sigma')\dsos}}{\lambda'}_{\pi_{i'}}|Aut(\sigma')|}{\norm{M_{\sigma'}}}$, we require that 
\[
ab = \frac{\sqrt{{w_i}w_{i'}}{\lambda'}_{\pi_i}{\lambda'}_{\pi_{i'}}|Aut(\sigma)| \cdot |Aut(\sigma')|}{c(\sigma)c(\sigma')\dsos\norm{M_{\sigma}}\norm{M_{\sigma'}}} \geq {w_j}\lam'_{\sigma}\lam'_{\sigma'}
\]
Rearranging, we need to choose the weights so that 
\[
w_j \leq \frac{\sqrt{{w_i}w_{i'}}{\lambda'}_{\pi_i}{\lambda'}_{\pi_{i'}}|Aut(\sigma)| \cdot |Aut(\sigma')|}{c(\sigma)c(\sigma')\dsos\lam'_{\sigma}\lam'_{\sigma'}\norm{M_{\sigma}}\norm{M_{\sigma'}}}
\]
We have that 
$\frac{\lambda'_{\sigma}\norm{M_{\sigma}}}{\lambda'_{\pi_i}|Aut(\sigma)|}$ is $\tilde{O}\left(\frac{k^3}{n}\right)^{\frac{|U_{\sigma}| - |V_{\sigma}|}{2}}$.
To see this, we make the following observations:
\begin{enumerate}
    \item $\lam'_{\sigma} \approx \left(\frac{k}{n}\right)^{|V(\sigma)| - \frac{|V_{\sigma}|}{2}}\left(\sqrt{\frac{p}{1-p}}\right)^{|E(\sigma)|}$
    \item ${\lambda'}_{\pi_i} \approx \left(\frac{k}{n}\right)^{\frac{|U_{\sigma}|}{2}}$
    \item $\frac{\norm{M_{\sigma}}}{|Aut(\sigma)|}$ is $\tilde{O}\left(n^{\frac{|V(\sigma) \setminus S|}{2}}\left(\sqrt{\frac{1-p}{p}}\right)^{|E(S)|}\right)$ where $S$ is the sparse minimum vertex separator of $\sigma$.
    \item $|E(\sigma) \setminus E(S)| \geq |V(\sigma)| - |S| + |V_{\sigma}| - |U_{\sigma}|$ as there are at most $|U_{\sigma}| - |V_{\sigma}|$ connected components of $\sigma$ which do not contain a vertex in $S$.
    \item Since $\sigma$ is a left shape and $S$ is a vertex separator, $|S| \geq |V_{\sigma}|$.
    \item Since $\sqrt{\frac{np}{1-p}} > 1$ and $\frac{k}{n}\sqrt{\frac{np}{1-p}} \leq 1$, 
    \begin{align*}
        &\left(\frac{k}{n}\right)^{|V(\sigma)| - \frac{|U_{\sigma}| + |V_{\sigma}| }{2}}n^{\frac{|V(\sigma) \setminus S|}{2}}\left(\sqrt{\frac{p}{1-p}}\right)^{|V(\sigma)| - |S| + |V_{\sigma}| - |U_{\sigma}|} \\
        &\leq \left(\sqrt{\frac{np}{1-p}}\right)^{|V_{\sigma}| - |S|}\left(\frac{k}{n}\sqrt{\frac{np}{1-p}}\right)^{|V(\sigma)| - |U_{\sigma}|}
        \left(\frac{k}{n}\right)^{\frac{|U_{\sigma}| - |V_{\sigma}|}{2}}n^{\frac{|U_{\sigma}| - |V_{\sigma}|}{2}} \\
        &\leq k^{\frac{|U_{\sigma}| - |V_{\sigma}|}{2}}
        \end{align*}
    Thus, if we take $w_j = \tilde{O}\left(k^{D_{SoS} - j}\right)$ then this equation will be satisfied for all $C'$-sparse $\sigma$ and $\sigma'$. Note that as long as $E_{mid}(\sigma) \leq V(\sigma) + CD_{SoS}$, the factors of $\frac{k}{n}\sqrt{\frac{np}{1-p}}$ are enough to handle $c(\sigma)$. 
    By analyzing their Frobenius norm, it can be shown that with high probability, the terms where $E_{mid}(\sigma) > V(\sigma) + CD_{SoS}$ or $E_{mid}(\sigma') > V(\sigma') + CD_{SoS}$ have norm $n^{-\Omega(CD_{SoS})}$ and are thus negligible.
\end{enumerate}
\end{proof}
